#!/usr/bin/env node
/**
 * Demo content for the storefront: a mock Cloudflare-merch catalog (fictional, unofficial, USD) with vocabulary,
 * brands, categories, products with variants and prices, bundles, a membership with a recurring price, and the
 * Homepage entry (CTA, shop-the-look points, spotlight callouts). The data lives in `scripts/lib/merch-catalog.mjs`,
 * the photos in `apps/storefront/public/merch/` (generated by `pnpm art`, committed: no network needed).
 * Dependency-free (Node >= 24), idempotent: everything is matched by slug or name, so running it again updates in place.
 *
 * Usage:  pnpm seed [-- --only site,apparel,accessory,bundle,membership,home]
 * Env:    EMDASH_URL                    base URL of the storefront (default http://localhost:4360; a deployed site: https://...)
 *         EMDASH_TOKEN                  personal access token (ec_pat_..., admin -> Settings -> API Tokens). Set: bearer auth,
 *                                       works against a deployed site, never calls a dev route, needs the setup wizard done.
 *                                       Unset: the dev login of `astro dev`.
 *         SEED_SYNC_TIMEOUT_SECONDS     how long the final Stripe catalog sync may take (default 300)
 *
 * After the products it queues the plugin's catalog resync and drives it to the end (Stripe Products and Prices
 * for every variant), when a Stripe key is configured; without a key it prints what to run later. Never against a
 * live key. A sync that times out or has failures ends the script with exit code 1.
 *
 * With the dev login it also creates the dev-only `feedback` collection (seed/dev-tools.json), which the production
 * seed leaves out; with a token it never does. With a token it first checks the scopes it needs and stops before
 * writing when one is missing (docs/production.md, "Seeding a deployed site").
 *
 * Dev login: needs the dev server running. A fresh database gets the schema through the dev setup. See "Fresh clone" in README.md.
 * Each photo is uploaded once to the EmDash media library (matched by file name).
 */
import { existsSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { HOTSPOTS } from "./art/hotspots.mjs";
import {
	ACCESSORIES,
	APPAREL,
	BRANDS,
	BUNDLES,
	CATEGORIES,
	COLOURS,
	CURRENCY,
	HOME,
	MEMBERSHIP,
	PRODUCT_TYPES,
	SITE,
	SIZES,
} from "./lib/merch-catalog.mjs";
import { ensureDevTools } from "./lib/dev-tools.mjs";
import { AUTH_MODE, createClient, preflightScopes, resolveTarget, SeedAccessError } from "./lib/emdash-client.mjs";
import { syncStripeCatalog } from "./lib/sync-stripe-catalog.mjs";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const ART = join(ROOT, "apps", "storefront", "public", "merch");
const PLUGIN = "stripe-commerce";

// ---------------------------------------------------------------- http
let client;
const call = (method, path, options) => client.call(method, path, options);

const unwrap = (response) => response.data ?? response;

// ---------------------------------------------------------------- content helpers
const cache = new Map();

const listAll = async (collection, refresh = false) => {
	if (!refresh && cache.has(collection)) return cache.get(collection);
	const items = [];
	let cursor;
	do {
		const data = unwrap(await call("GET", `/content/${collection}?limit=100${cursor ? `&cursor=${cursor}` : ""}`));
		items.push(...data.items);
		cursor = data.nextCursor;
	} while (cursor);
	cache.set(collection, items);
	return items;
};

const find = async (collection, key, field) => {
	const items = await listAll(collection);
	return items.find((item) => (field === undefined ? item.slug === key : item.data[field] === key));
};

/** Create or update (by slug, or by data[matchField]); optionally publish. Returns the item. */
const ensure = async (collection, data, { refs, slug, matchField, publish = true } = {}) => {
	const existing = slug ? await find(collection, slug) : await find(collection, data[matchField], matchField);
	const body = { data };
	if (refs !== undefined) body.references = refs;
	let item;
	if (existing) {
		item = unwrap(await call("PUT", `/content/${collection}/${existing.id}`, { body })).item;
	} else {
		if (slug) body.slug = slug;
		item = unwrap(await call("POST", `/content/${collection}`, { body })).item;
		cache.delete(collection);
	}
	if (publish && (item.status !== "published" || item.draftRevisionId)) {
		await call("POST", `/content/${collection}/${item.id}/publish`, { body: {} });
	}
	return item;
};

const portable = (...paragraphs) =>
	paragraphs.map((text, i) => ({
		_type: "block",
		_key: `b${i}`,
		style: "normal",
		markDefs: [],
		children: [{ _type: "span", _key: `s${i}`, text, marks: [] }],
	}));

// ---------------------------------------------------------------- media
const media = new Map();

/** The committed mock art as a Blob (`pnpm art` regenerates the folder). */
const photo = async (filename) => {
	const path = join(ART, filename);
	if (!existsSync(path)) throw new Error(`Missing art ${filename} in apps/storefront/public/merch/: run "pnpm art" first`);
	return new Blob([readFileSync(path)], { type: "image/png" });
};

const upload = async (filename, alt) => {
	if (media.has(filename)) return media.get(filename);
	let cursor;
	do {
		const data = unwrap(await call("GET", `/media?limit=100${cursor ? `&cursor=${cursor}` : ""}`));
		const hit = data.items.find((item) => item.filename === filename);
		if (hit) {
			media.set(filename, hit);
			return hit;
		}
		cursor = data.nextCursor;
	} while (cursor);
	const form = new FormData();
	form.set("alt", alt);
	form.set("file", await photo(filename), filename);
	const item = unwrap(await call("POST", "/media", { form })).item;
	media.set(filename, item);
	return item;
};

/** What the admin's media picker stores for a library item: a local-provider value without `src`. */
const imageValue = async (filename, alt) => {
	const item = await upload(filename, alt);
	return {
		provider: "local",
		id: item.id,
		filename: item.filename,
		mimeType: item.mimeType || "image/png",
		alt,
		width: item.width,
		height: item.height,
	};
};

/** A media value for the points widget (a json field): like the admin picker, it carries the storage key in `meta`. */
const pointsImage = async (filename, alt) => {
	const item = await upload(filename, alt);
	return { ...(await imageValue(filename, alt)), meta: { storageKey: item.storageKey } };
};

const gallery = async (files, alt) =>
	Promise.all(files.map(async (file, i) => ({ image: await imageValue(file, alt), alt: `${alt} (${i + 2})` })));

// ---------------------------------------------------------------- vocabulary
const seedVocabulary = async () => {
	const v = { attr: {}, type: {}, brand: {}, cat: {} };
	const attr = (name, code, extra) =>
		ensure("attributes", { name, storefront_label: name, code, ...extra }, { matchField: "name" });
	const size = await attr("Size", "size", { input_type: "select", presentation: "buttons", is_filterable: true });
	const colour = await attr("Colour", "colour", { input_type: "select", presentation: "swatch", is_filterable: true });
	const material = await attr("Material", "material", { input_type: "text" });
	const weight = await attr("Weight", "weight_g", { input_type: "number", unit: "g" });
	const waterproof = await attr("Waterproof", "waterproof", { input_type: "boolean" });
	const includes = await attr("Includes", "includes", { input_type: "text" });
	v.attr = {
		size: size.id,
		colour: colour.id,
		material: material.id,
		weight: weight.id,
		waterproof: waterproof.id,
		includes: includes.id,
	};

	const makeValues = async (attrItem, rows) => {
		const out = {};
		for (const [label, code, swatch] of rows) {
			const data = { label, code, ...(swatch ? { swatch } : {}) };
			const values = await listAll("attribute_values");
			const existing = values.find((it) => it.data.label === label && it.data.code === code);
			let item;
			if (existing) {
				item = unwrap(await call("PUT", `/content/attribute_values/${existing.id}`, { body: { data } })).item;
			} else {
				item = unwrap(await call("POST", "/content/attribute_values", { body: { data } })).item;
				cache.delete("attribute_values");
			}
			if (item.status !== "published") await call("POST", `/content/attribute_values/${item.id}/publish`, { body: {} });
			out[label] = item.id;
		}
		// ordered children on the parent side
		await ensure("attributes", { ...attrItem.data }, { refs: { values: Object.values(out) }, slug: attrItem.slug });
		return out;
	};
	v.sizeValues = await makeValues(size, SIZES);
	v.colourValues = await makeValues(colour, COLOURS);

	const ptype = async (key, { name, axes, specs, required }) =>
		(
			await ensure(
				"product_types",
				{ name, code: key },
				{
					refs: {
						variant_axes: axes.map((axis) => v.attr[axis]),
						allowed_values: [],
						spec_attributes: specs.map((spec) => v.attr[spec]),
						required_specs: required.map((spec) => v.attr[spec]),
					},
					matchField: "name",
				},
			)
		).id;
	for (const [key, definition] of Object.entries(PRODUCT_TYPES)) v.type[key] = await ptype(key, definition);

	for (const { slug, name, website, intro } of BRANDS) {
		const data = {
			name,
			website,
			intro,
			description: portable(intro, `${name} is a fictional label of the unofficial Cloudflare Merch demo shop.`),
		};
		v.brand[slug] = (await ensure("brands", data, { slug })).id;
	}

	for (const [slug, name, parent, intro, image] of CATEGORIES) {
		const data = { name, intro, image: await imageValue(image, name), description: portable(intro) };
		v.cat[slug] = (await ensure("product_categories", data, { refs: { parent: parent ? [v.cat[parent]] : [] }, slug })).id;
	}
	return v;
};

// ---------------------------------------------------------------- products
const charSum = (text) => [...text].reduce((sum, ch) => sum + ch.charCodeAt(0), 0);
const stockFor = (slug, label, i) => 4 + ((charSum(slug + label) + i * 7) % 24);

const specsForm = (v, { material, weight, waterproof, includes }) => ({
	...(material === undefined ? {} : { [`spec_${v.attr.material}`]: material }),
	...(weight === undefined ? {} : { [`spec_${v.attr.weight}`]: weight }),
	...(waterproof === undefined ? {} : { [`spec_${v.attr.waterproof}`]: waterproof }),
	...(includes === undefined ? {} : { [`spec_${v.attr.includes}`]: includes }),
});

const panel = async (productId, kind, body) =>
	unwrap(await call("POST", `/content/products/${productId}/plugin-extensions/${PLUGIN}/panel/${kind}`, { body }));

/** [size, colour, variant id] of a product, from its variants relation (titles look like "Product — M / Black"). */
const listVariants = async (productId) => {
	const data = unwrap(await call("GET", `/content/products/${productId}/references/catalog_product_variants/children?limit=100`));
	const order = new Map(SIZES.map(([label], n) => [label, n]));
	return data.children
		.map((child) => {
			const label = child.title.split(" — ").pop();
			const [size, colour] = label.split("/").map((part) => part.trim());
			return [size, colour, child.id];
		})
		.sort((a, b) => a[1].localeCompare(b[1]) || (order.get(a[0]) ?? 9) - (order.get(b[0]) ?? 9));
};

const seedApparel = async (v) => {
	for (const p of APPAREL) {
		const data = {
			title: p.title,
			description: portable(...p.copy),
			price: p.price,
			has_variants: true,
			track_inventory: true,
			allow_backorder: false,
			image: await imageValue(p.image, p.title),
			gallery: await gallery([p.extra], p.title),
		};
		const refs = { product_type: [v.type.apparel], brand: [v.brand[p.brand]], categories: p.cats.map((c) => v.cat[c]) };
		const product = await ensure("products", data, { refs, slug: p.slug, publish: false });
		await panel(product.id, "specification", {
			type: "form_submit",
			action_id: "save_specification",
			block_id: "specification",
			values: specsForm(v, p),
		});
		await panel(product.id, "variants", {
			type: "form_submit",
			action_id: "generate_variants",
			block_id: "variants_generate",
			values: {
				[`axis_${v.attr.size}`]: p.sizes.map((s) => v.sizeValues[s]),
				[`axis_${v.attr.colour}`]: p.colours.map((c) => v.colourValues[c]),
			},
		});
		const skip = new Set(p.skip ?? []);
		const variants = await listVariants(product.id);
		let kept = 0;
		for (const [i, [size, colour, id]] of variants.entries()) {
			const key = `${size}/${colour}`;
			if (skip.has(key)) {
				await call("DELETE", `/content/product_variants/${id}`); // a subset of the grid: drop the combination
				continue;
			}
			kept += 1;
			const vdata = { stock: stockFor(p.slug, size + colour, i) };
			if (p.overrides[key] !== undefined) vdata.price = p.overrides[key];
			if (p.colourImages[colour]) {
				vdata.image = await imageValue(p.colourImages[colour], `${p.title} ${colour}`);
				vdata.gallery = await gallery([p.extra], `${p.title} ${colour}`);
			}
			await call("PUT", `/content/product_variants/${id}`, { body: { data: vdata } });
		}
		await call("POST", `/content/products/${product.id}/publish`, { body: {} });
		console.log(`apparel ${p.slug}: ${kept} variants`);
	}
};

const inventoryOnHand = async (id) =>
	unwrap(await call("POST", `/plugins/${PLUGIN}/admin/inventory/get`, { body: { kind: "product", id } }))?.onHand ?? 0;

/** A product without variants: its own price and a stock level (accessories and bundles). */
const seedSimple = async (v, p, { type, kind }) => {
	const data = {
		title: p.title,
		description: portable(...p.copy),
		price: p.price,
		sku: p.sku,
		has_variants: false,
		track_inventory: true,
		allow_backorder: false,
		image: await imageValue(p.image, p.title),
		gallery: await gallery(p.gallery, p.title),
	};
	const refs = { product_type: [v.type[type]], brand: [v.brand[p.brand]], categories: p.cats.map((c) => v.cat[c]) };
	const product = await ensure("products", data, { refs, slug: p.slug, publish: false });
	await panel(product.id, "specification", {
		type: "form_submit",
		action_id: "save_specification",
		block_id: "specification",
		values: specsForm(v, p),
	});
	await call("POST", `/content/products/${product.id}/publish`, { body: {} });
	const have = await inventoryOnHand(product.id);
	if (have < p.stock) {
		await call("POST", `/plugins/${PLUGIN}/admin/inventory/adjust`, {
			body: { kind: "product", id: product.id, delta: p.stock - have, reason: "Initial stock (seed)" },
		});
	}
	console.log(`${kind} ${p.slug}`);
};

const seedAccessories = async (v) => {
	for (const p of ACCESSORIES) await seedSimple(v, p, { type: "accessory", kind: "accessory" });
};

const seedBundles = async (v) => {
	for (const p of BUNDLES) await seedSimple(v, p, { type: "bundle", kind: "bundle" });
};

const seedMembership = async (v) => {
	const m = MEMBERSHIP;
	const data = {
		title: m.title,
		description: portable(...m.copy),
		price: m.price,
		sku: m.sku,
		has_variants: false,
		track_inventory: false,
		allow_backorder: false,
		image: await imageValue(m.image, m.title),
		gallery: await gallery(m.gallery, m.title),
	};
	const refs = { product_type: [v.type.membership], brand: [v.brand[m.brand]], categories: m.cats.map((c) => v.cat[c]) };
	const product = await ensure("products", data, { refs, slug: m.slug, publish: false });
	await ensure(
		"prices",
		{
			nickname: m.recurring.nickname,
			type: "recurring",
			unit_amount: m.recurring.amount,
			currency: CURRENCY,
			interval: m.recurring.interval,
			interval_count: 1,
			trial_days: m.recurring.trialDays,
			tax_behavior: "unspecified",
			lookup_key: m.recurring.lookupKey,
			is_active: true,
			is_default: false,
		},
		{ refs: { product: [product.id], variant: [] }, matchField: "nickname" },
	);
	await call("POST", `/content/products/${product.id}/publish`, { body: {} });
	console.log(`membership ${m.slug}`);
};

// ---------------------------------------------------------------- site identity
/** The shop identity (a partial settings update merges, so re-running changes nothing). */
const seedSiteIdentity = async () => {
	await call("POST", "/settings", { body: { title: SITE.title, tagline: SITE.tagline } });
	console.log("site identity: title and tagline");
};

// ---------------------------------------------------------------- homepage
/** Hotspot percentages from `scripts/art/hotspots.mjs` (derived from the art's own drawing coordinates). */
const point = (n, spot, rest) => ({ id: `point-${n}`, x: spot.x, y: spot.y, ...rest });

/** The Homepage entry: CTA band, shop-the-look points on the desk setup, spotlight callouts on the jacket. */
const seedHome = async () => {
	// A deployed site has the schema from seed.json but no sample content (the setup wizard asks for it): create the entry.
	const home = (await find("home", "home")) ?? (await ensure("home", { title: "Homepage" }, { slug: "home", publish: false }));
	const lookSpots = Object.entries(HOME.look.products);
	const calloutSpots = Object.entries(HOME.spotlight.callouts);
	const data = {
		cta_eyebrow: HOME.cta.eyebrow,
		cta_heading: HOME.cta.heading,
		cta_text: HOME.cta.text,
		cta_button_label: HOME.cta.buttonLabel,
		cta_button_url: HOME.cta.buttonUrl,
		cta_image: await imageValue(HOME.cta.image, HOME.cta.imageAlt),
		look_hotspots: {
			image: await pointsImage(HOME.look.image, HOME.look.imageAlt),
			points: lookSpots.map(([key, productSlug], i) => point(i + 1, HOTSPOTS.lookDesk[key], { productSlug })),
		},
		spotlight_callouts: {
			image: await pointsImage(HOME.spotlight.image, HOME.spotlight.imageAlt),
			points: calloutSpots.map(([key, text], i) => point(i + 1, HOTSPOTS.spotlightJacket[key], text)),
		},
	};
	await call("PUT", `/content/home/${home.id}`, { body: { data } });
	await call("POST", `/content/home/${home.id}/publish`, { body: {} });
	console.log("home: CTA, shop-the-look points, spotlight callouts");
};

// ---------------------------------------------------------------- stripe catalog sync
const SYNC_TIMEOUT_MS = Math.max(10, Number(process.env.SEED_SYNC_TIMEOUT_SECONDS ?? 300)) * 1000;
const syncCatalog = () => syncStripeCatalog({ call: (method, path, options) => call(method, path, options), plugin: PLUGIN, timeoutMs: SYNC_TIMEOUT_MS });

// ---------------------------------------------------------------- main
const DEV_TOOLS_SEED = join(ROOT, "apps", "storefront", "seed", "dev-tools.json");

/** The token scopes each part of the seed uses (the plugin's admin routes need the admin scope). */
const scopesFor = (wants) => {
	const products = ["apparel", "accessory", "bundle", "membership"].some(wants);
	const scopes = new Set();
	if (wants("site")) scopes.add("settings:manage");
	if (products || wants("home")) ["content:read", "content:write", "media:read", "media:write"].forEach((scope) => scopes.add(scope));
	if (products) scopes.add("admin");
	return [...scopes];
};

const main = async () => {
	const flag = process.argv.indexOf("--only");
	const only = flag === -1 ? null : process.argv[flag + 1].split(",");
	const wants = (name) => only === null || only.includes(name);
	client = createClient({ target: resolveTarget() });
	await client.login();
	if (client.mode === AUTH_MODE.TOKEN) {
		console.log(`seeding ${client.origin} with an access token`);
		await preflightScopes(client, scopesFor(wants));
	} else {
		// A dev server only: the Notes tool of the editing pill needs its collection, which the production seed leaves out.
		const created = await ensureDevTools({ call, fragmentPath: DEV_TOOLS_SEED });
		if (created.length > 0) console.log(`dev tools: created the ${created.join(", ")} collection`);
	}
	if (wants("site")) await seedSiteIdentity();
	const products = ["apparel", "accessory", "bundle", "membership"];
	const hasProducts = products.some(wants);
	if (hasProducts) {
		const v = await seedVocabulary();
		console.log("vocabulary ok");
		if (wants("apparel")) await seedApparel(v);
		if (wants("accessory")) await seedAccessories(v);
		if (wants("bundle")) await seedBundles(v);
		if (wants("membership")) await seedMembership(v);
	}
	if (wants("home")) await seedHome();
	const outcome = hasProducts ? await syncCatalog() : null;
	console.log("done");
	if (outcome === "timeout" || outcome === "failed") process.exitCode = 1;
};

main().catch((error) => {
	console.error(error instanceof SeedAccessError ? `seed: ${error.message}` : error instanceof Error ? error.message : error);
	process.exit(1);
});
